# Lot 16 : « --exit-on-error » retirée, équivalente pour l'essai (pg_restore sort de toute façon en erreur,
# et le script s'arrête).
# Lot 15 : « not isinstance(valeur, dict) » → « valeur is None » retirée, équivalente (une trace de document
# vaut toujours un dictionnaire ou rien).
# Lot 14 : « actifs == "1" » → « actifs != "0" » retirée, équivalente (la valeur est déjà limitée à 0 ou 1).
# Lot 13 : retirées car équivalentes — l'année dans le test « échéance dans le mois » (calculée depuis le 1er
# du mois, elle ne peut pas tomber le même mois d'une autre année) ; « obligations » ajouté à BIENTOT (la vraie
# route est déclarée avant et l'emporte toujours).
# Lot 12 : « empreinte is None » → « not empreinte » retirée, équivalente (une empreinte n'est jamais vide).
# Mutations retirées car devenues équivalentes : depuis le lot 10, les imports en chaîne chargent déjà
# toutes les tables pour la commande « preparer » et les tâches de rappel et d'envoi WhatsApp. Les imports
# explicites de app.models restent dans le code par précaution.


def lancer_tests() -> bool:
    resultat = subprocess.run(
        [sys.executable, "-m", "pytest", "-x", "-q", "-p", "no:warnings"],
        cwd=RACINE,
        capture_output=True,
    )
    return resultat.returncode == 0


def main(lot: str) -> int:
    survivantes = []
    for fichier, avant, apres in MUTATIONS[lot]:
        chemin = RACINE / fichier
        original = chemin.read_text()
        if original.count(avant) != 1:
            print(f"MUTATION INVALIDE ({fichier}) : texte introuvable ou ambigu : {avant!r}")
            return 2
        chemin.write_text(original.replace(avant, apres))
        try:
            tue = not lancer_tests()
        finally:
            chemin.write_text(original)
        print(f"{'tuée     ' if tue else 'SURVIVANTE'} {fichier} : {avant[:60]!r}")
        if not tue:
            survivantes.append((fichier, avant))
    total = len(MUTATIONS[lot])
    print(f"\n{total - len(survivantes)}/{total} mutations tuées.")
    return 1 if survivantes else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1] if len(sys.argv) > 1 else "lot01"))
